head.script:
{
  "@context": "https://schema.org",
  "@type": "WebSite",
  "name": "벤스페이퍼",
  "alternateName": "BensPaper",
  "url": "",
  "description": "엑셀·구글 스프레드시트 함수, AI 활용법, 생활 속 컴퓨터·스마트폰 팁을 따라 하기 쉽게 단계별로 정리하는 블로그",
  "inLanguage": "ko",
  "publisher": { "@type": "Person", "name": "엉클벤", "url": "https://www.benspaper.info/p/about.html" },
  "potentialAction": {
    "@type": "SearchAction",
    "target": {
      "@type": "EntryPoint",
      "urlTemplate": ""
    },
    "query-input": "required name=search_term_string"
  }
}

head.b:skin:
/* =========================================================
   BensPaper(벤스페이퍼) — 엑셀·AI·일상 팁 블로그 테마 (2026-09 3기)
   2026 디자인 트렌드: 다크모드 기본, 카드형 그리드, 글래스모피즘 포인트,
   미니멀 타이포그래피. 브랜드 컬러 유지(남색/하늘색/주황).
   ========================================================= */

:root {
  --bg: #f5f7fa;
  --bg-elevated: #ffffff;
  --text: #1a2433;
  --text-muted: #5b6b73;
  --border: #e2e8ef;
  --card-bg: #ffffff;
  --navy: #1b4965;
  --blue: #2c6b8f;
  --blue-light: #5fa8d3;
  --orange: #ee6c4d;
  --shadow-sm: 0 1px 3px rgba(15,23,42,.06), 0 1px 2px rgba(15,23,42,.04);
  --shadow-md: 0 8px 24px rgba(15,23,42,.10);
  --radius: 14px;
  --radius-sm: 8px;
  --maxw: 1180px;
  --content-w: 800px;
}

:root[data-theme="dark"] {
  --bg: #0b1220;
  --bg-elevated: #121a2b;
  --text: #e7edf5;
  --text-muted: #93a3b8;
  --border: #223047;
  --card-bg: #121a2b;
  --navy: #7fb3d3;
  --blue: #8fc4e8;
  --blue-light: #6fbde0;
  --orange: #ff8a68;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.3);
  --shadow-md: 0 12px 32px rgba(0,0,0,.45);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #0b1220;
    --bg-elevated: #121a2b;
    --text: #e7edf5;
    --text-muted: #93a3b8;
    --border: #223047;
    --card-bg: #121a2b;
    --navy: #7fb3d3;
    --blue: #8fc4e8;
    --blue-light: #6fbde0;
    --orange: #ff8a68;
    --shadow-sm: 0 1px 3px rgba(0,0,0,.3);
    --shadow-md: 0 12px 32px rgba(0,0,0,.45);
  }
}

/* === 라이트 테마 통일 (글이 밝은 배경 기준으로 작성됨) === */
/* 다크 변수들을 라이트로 되돌려 흰색 본문/어두운 배경 충돌 제거 */
:root[data-theme="dark"] {
  --bg: #f5f7fa; --bg-elevated: #ffffff; --text: #1a2433; --text-muted: #5b6b73;
  --border: #e2e8ef; --card-bg: #ffffff; --navy: #1b4965; --blue: #2c6b8f;
  --blue-light: #5fa8d3; --orange: #ee6c4d;
  --shadow-sm: 0 1px 3px rgba(15,23,42,.06), 0 1px 2px rgba(15,23,42,.04);
  --shadow-md: 0 8px 24px rgba(15,23,42,.10);
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #f5f7fa; --bg-elevated: #ffffff; --text: #1a2433; --text-muted: #5b6b73;
    --border: #e2e8ef; --card-bg: #ffffff; --navy: #1b4965; --blue: #2c6b8f;
    --blue-light: #5fa8d3; --orange: #ee6c4d;
    --shadow-sm: 0 1px 3px rgba(15,23,42,.06), 0 1px 2px rgba(15,23,42,.04);
    --shadow-md: 0 8px 24px rgba(15,23,42,.10);
  }
}
/* 다크모드 토글 숨김 (라이트 통일) */
#themeToggle { display: none !important; }
/* 본문 흰색 슬래브 제거 → 페이지 배경과 매끄럽게 이어짐 */
.post-body > div { background: transparent !important; box-shadow: none !important; }

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, 'Apple SD Gothic Neo', 'Malgun Gothic', '맑은 고딕', 'Noto Sans KR', 'Segoe UI', sans-serif;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  transition: background .2s ease, color .2s ease;
}
a { color: var(--blue); text-decoration: none; }
a:hover { text-decoration: underline; }
img { max-width: 100%; height: auto; display: block; }
.wrap { max-width: var(--maxw); margin: 0 auto; padding: 0 20px; }

/* Reading progress bar */
#readingProgress {
  position: fixed; top: 0; left: 0; height: 3px; width: 0%;
  background: linear-gradient(90deg, var(--blue-light), var(--orange));
  z-index: 999; transition: width .1s linear;
}

/* Header */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: color-mix(in srgb, var(--bg-elevated) 82%, transparent);
  backdrop-filter: blur(14px) saturate(160%);
  -webkit-backdrop-filter: blur(14px) saturate(160%);
  border-bottom: 1px solid var(--border);
}
.site-header .wrap {
  display: flex; align-items: center; justify-content: space-between;
  padding-top: 14px; padding-bottom: 14px; gap: 16px;
}
.brand { display: flex; align-items: center; gap: 10px; }
.brand-mark {
  width: 34px; height: 34px; border-radius: 9px;
  background: linear-gradient(135deg, var(--navy), var(--blue));
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-weight: 800; font-size: 16px; flex-shrink: 0;
}
.brand-text p { margin: 0; font-size: 11px; color: var(--text-muted); }
.brand-text a { color: var(--text); }
.brand-text a:hover { text-decoration: none; }

.main-nav { display: flex; align-items: center; gap: 2px; }
.main-nav .section, .main-nav .widget { margin: 0; padding: 0; display: flex; }
.main-nav ul { list-style: none; display: flex; gap: 2px; margin: 0; padding: 0; }
.main-nav a {
  display: inline-block; padding: 8px 12px; border-radius: 999px;
  color: var(--text); font-size: 14px; font-weight: 500;
}
.main-nav a:hover { background: var(--border); text-decoration: none; }

.header-actions { display: flex; align-items: center; gap: 8px; }
.icon-btn {
  width: 38px; height: 38px; border-radius: 999px; border: 1px solid var(--border);
  background: var(--bg-elevated); color: var(--text); cursor: pointer;
  display: flex; align-items: center; justify-content: center; font-size: 16px;
}
.icon-btn:hover { border-color: var(--blue-light); }

.search-box { position: relative; display: none; }
.search-box.open { display: block; }
.search-box input {
  border: 1px solid var(--border); border-radius: 999px; padding: 8px 14px;
  font-size: 14px; background: var(--bg-elevated); color: var(--text); width: 200px;
}

/* mobile nav toggle (CSS-only) */
.menu-toggle-checkbox { display: none; }
.menu-toggle-label { display: none; }
@media (max-width: 780px) {
  .main-nav { display: none; position: absolute; top: 100%; left: 0; right: 0;
    background: var(--bg-elevated); border-bottom: 1px solid var(--border); padding: 8px 20px 16px; }
  .main-nav .section, .main-nav .widget { display: block; }
  .main-nav ul { flex-direction: column; }
  .menu-toggle-checkbox:checked ~ .main-nav { display: block; }
  .menu-toggle-label {
    display: flex; width: 38px; height: 38px; border-radius: 999px; border: 1px solid var(--border);
    align-items: center; justify-content: center; cursor: pointer; font-size: 18px;
  }
  .search-box input { width: 140px; }
}

/* Hero (homepage only) */
.hero {
  padding: 56px 0 40px; text-align: center;
}
.hero h2 {
  font-size: clamp(26px, 4vw, 40px); font-weight: 800; letter-spacing: -.02em; margin: 0 0 12px;
  background: linear-gradient(135deg, var(--navy), var(--blue-light));
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.hero p { color: var(--text-muted); font-size: 16px; max-width: 560px; margin: 0 auto; }

/* Post grid (index / archive / search) */
.post-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 24px; padding: 8px 0 48px;
}
.post-card {
  background: var(--card-bg); border: 1px solid var(--border); border-radius: var(--radius);
  overflow: hidden; box-shadow: var(--shadow-sm); transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
  display: flex; flex-direction: column;
}
.post-card:hover {
  transform: translateY(-4px); box-shadow: var(--shadow-md); border-color: var(--blue-light);
}
.post-card-thumb { aspect-ratio: 1200/630; overflow: hidden; background: linear-gradient(135deg, var(--navy), var(--blue-light)); }
.post-card-thumb img { width: 100%; height: 100%; object-fit: cover; }
.post-card-thumb.placeholder { display: flex; align-items: center; justify-content: center; color: #fff; font-size: 34px; font-weight: 800; opacity: .55; }
.post-card-body { padding: 18px 20px 20px; flex: 1; display: flex; flex-direction: column; }
.post-card-meta { font-size: 12px; color: var(--text-muted); margin-bottom: 8px; display: flex; gap: 8px; flex-wrap: wrap; }
.post-card-title { font-size: 18px; font-weight: 800; margin: 0 0 8px; line-height: 1.4; color: var(--text); }
.post-card-title a { color: inherit; }
.post-card-title a:hover { text-decoration: none; color: var(--blue); }
.post-card-snippet { font-size: 14px; color: var(--text-muted); flex: 1; margin: 0 0 12px;
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.post-card-labels { display: flex; gap: 6px; flex-wrap: wrap; }
.chip {
  font-size: 11px; font-weight: 700; padding: 3px 9px; border-radius: 999px;
  background: color-mix(in srgb, var(--blue-light) 18%, transparent); color: var(--blue);
}

/* Single post / page */
.post-single { max-width: var(--content-w); margin: 0 auto; padding: 36px 20px 60px; }
.post-single-header { margin-bottom: 24px; }
.post-single-title { font-size: clamp(24px, 4vw, 32px); font-weight: 800; letter-spacing: -.02em; margin: 0 0 12px; color: var(--text); }
.post-single-meta { font-size: 13px; color: var(--text-muted); display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.post-single-meta .chip { }

.post-toc {
  background: var(--bg-elevated); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 16px 20px; margin: 24px 0; font-size: 14px;
}
.post-toc p { margin: 0 0 8px; font-weight: 700; color: var(--navy); }
.post-toc ol { margin: 0; padding-left: 20px; }
.post-toc a { color: var(--text-muted); }

.post-body { font-size: 17px; color: var(--text); }
.post-body img, .post-body svg { border-radius: var(--radius); }
.post-body h2, .post-body h3 { color: var(--navy); }
:root[data-theme="dark"] .post-body h2, :root[data-theme="dark"] .post-body h3 { color: var(--blue-light); }

/* 모바일 본문 최적화 (기존/신규 글 전체에 적용) */
@media (max-width: 600px) {
  /* 좌우 여백 3중 중첩 제거: .wrap(15px)만 유일한 게터로, .post-single·본문div는 0 */
  .wrap { padding-left: 15px; padding-right: 15px; }
  .post-single { padding-left: 0; padding-right: 0; padding-top: 20px; }
  .post-body { font-size: 16px; }
  /* 글 본문 인라인 래퍼(고정 17px·좌우 4px 여백) 모바일 조정 */
  .post-body > div { font-size: 16px !important; line-height: 1.68 !important;
    max-width: none !important; padding-left: 0 !important; padding-right: 0 !important; }
  .post-body h2 { font-size: 20px !important; line-height: 1.35; }
  /* 프롬프트/코드 블록: 가로 스크롤 대신 줄바꿈 (모바일 복사 편의) */
  .post-body pre { white-space: pre-wrap !important; word-break: break-word; }
  /* 표: 넘치면 가로 스크롤 */
  .post-body table { display: block; overflow-x: auto; -webkit-overflow-scrolling: touch; }
}

.post-footer { margin-top: 40px; padding-top: 24px; border-top: 1px solid var(--border);
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 12px; }
.share-row { display: flex; gap: 8px; }
.share-row a {
  width: 36px; height: 36px; border-radius: 999px; border: 1px solid var(--border);
  display: flex; align-items: center; justify-content: center; font-size: 14px; color: var(--text);
}
.share-row a:hover { border-color: var(--blue-light); text-decoration: none; }

/* pagination */
.pagination { display: flex; justify-content: space-between; padding: 20px 0 48px; gap: 12px; }
.pagination a {
  padding: 10px 18px; border: 1px solid var(--border); border-radius: 999px; font-size: 14px; font-weight: 600;
  background: var(--bg-elevated); color: var(--text);
}
.pagination a:hover { border-color: var(--blue-light); text-decoration: none; }

/* comments (minimal) */
.comments-section { margin-top: 40px; padding-top: 24px; border-top: 1px solid var(--border); }
.comments-section h4 { font-size: 16px; font-weight: 800; color: var(--navy); }
.comment-item { padding: 12px 0; border-bottom: 1px solid var(--border); font-size: 14px; }
.comment-item .c-author { font-weight: 700; margin-right: 6px; }
.comment-item .c-time { color: var(--text-muted); font-size: 12px; }

/* sidebar (labels / popular, homepage only) */
.side-widgets { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px,1fr)); gap: 20px; padding: 0 0 48px; }
.side-card { background: var(--card-bg); border: 1px solid var(--border); border-radius: var(--radius); padding: 18px 20px; }
.side-card h3 { margin: 0 0 12px; font-size: 14px; font-weight: 800; color: var(--navy); }
.side-card ul { list-style: none; margin: 0; padding: 0; }
.side-card li { padding: 6px 0; font-size: 13px; border-bottom: 1px dashed var(--border); }
.side-card li:last-child { border-bottom: none; }

/* footer */
.site-footer { border-top: 1px solid var(--border); padding: 32px 0; margin-top: 20px; }
.site-footer .wrap { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 14px; }
.footer-links ul { list-style: none; display: flex; gap: 16px; margin: 0; padding: 0; flex-wrap: wrap; }
.footer-links a { color: var(--text-muted); font-size: 13px; }
.footer-copy { color: var(--text-muted); font-size: 13px; }

/* back to top */
#backToTop {
  position: fixed; right: 20px; bottom: 20px; width: 44px; height: 44px; border-radius: 999px;
  background: var(--navy); color: #fff; border: none; display: none; align-items: center; justify-content: center;
  cursor: pointer; box-shadow: var(--shadow-md); z-index: 90; font-size: 18px;
}
#backToTop.show { display: flex; }

/* empty state */
.empty-state { padding: 60px 20px; text-align: center; color: var(--text-muted); }

/* attribution (keep small, required-ish) */
.attribution { text-align: center; font-size: 11px; color: var(--text-muted); padding-bottom: 24px; }


/* ===== 3기 추가: 글 본문 컴포넌트 ===== */
.post-body p { margin: 0 0 18px; }
.post-body h2 { font-size: 24px; font-weight: 800; margin: 44px 0 14px; padding-top: 10px; border-top: 2px solid var(--border); letter-spacing: -.01em; }
.post-body h3 { font-size: 19px; font-weight: 800; margin: 28px 0 10px; }
.post-body ul, .post-body ol { padding-left: 22px; margin: 0 0 18px; }
.post-body li { margin: 6px 0; }
.post-body code { font-family: Consolas, 'D2Coding', monospace; background: #eef3f7; color: #1b4965; padding: 2px 6px; border-radius: 6px; font-size: .92em; }
.post-body pre { background: #0f2a3c; color: #e7edf5; padding: 16px 18px; border-radius: 10px; overflow-x: auto; font-size: 15px; line-height: 1.6; }
.post-body pre code { background: none; color: inherit; padding: 0; }
.post-body figure { margin: 8px 0 30px; text-align: center; }
.post-body figcaption { font-size: 13px; color: var(--text-muted); margin-top: 8px; }
.post-body table { width: 100%; border-collapse: collapse; margin: 8px 0 24px; font-size: 15px; }
.post-body th, .post-body td { border: 1px solid var(--border); padding: 10px 12px; text-align: left; vertical-align: top; }
.post-body th { background: #eaf2f8; color: var(--navy); font-weight: 700; }
.post-body kbd { display: inline-block; font-family: inherit; font-size: .88em; font-weight: 700; padding: 2px 8px; border: 1px solid #c3cfda; border-bottom-width: 3px; border-radius: 6px; background: #fff; color: var(--text); white-space: nowrap; }
.bp-summary { background: #eef6fb; border: 1px solid #cfe2ef; border-left: 5px solid var(--blue-light); border-radius: 12px; padding: 18px 22px; margin: 0 0 28px; }
.bp-summary p { margin: 0 0 8px; }
.bp-summary ul { margin: 0; }
.bp-summary-title { font-weight: 800; color: var(--navy); }
.bp-note { background: #fff8e6; border: 1px solid #f0dfae; border-left: 5px solid #e0a800; border-radius: 12px; padding: 14px 18px; margin: 18px 0 24px; }
.bp-note p { margin: 0; }
.bp-faq details { border: 1px solid var(--border); border-radius: 10px; padding: 12px 16px; margin: 10px 0; background: var(--bg-elevated); }
.bp-faq summary { font-weight: 700; cursor: pointer; color: var(--text); }
.bp-faq details p { margin: 10px 0 0; }
.bp-page h2 { font-size: 20px; font-weight: 800; margin: 32px 0 10px; color: var(--navy); border-top: none; padding-top: 0; }
.bp-page p, .bp-page li { font-size: 16px; }
.post-toc li { margin: 4px 0; }

/* 글쓴이 박스 */
.author-box { display: flex; gap: 16px; align-items: flex-start; margin-top: 40px; padding: 20px 22px; background: var(--bg-elevated); border: 1px solid var(--border); border-radius: var(--radius); }
.author-avatar { width: 52px; height: 52px; border-radius: 999px; flex-shrink: 0; background: linear-gradient(135deg, var(--navy), var(--blue-light)); color: #fff; font-weight: 800; font-size: 20px; display: flex; align-items: center; justify-content: center; }
.author-name { margin: 0 0 4px; font-weight: 800; color: var(--navy); }
.author-desc { margin: 0; font-size: 14px; color: var(--text-muted); }

/* 헤더 브랜드 */
.brand-title { margin: 0; font-size: 18px; font-weight: 800; letter-spacing: -.02em; }
.brand-title a { color: var(--text); }
.brand-title a:hover { text-decoration: none; }
.footer-copy a { color: var(--text-muted); }


/* ===== 3.3: 경로·시리즈·관련 글·링크 구분 ===== */
.breadcrumb { font-size: 13px; color: var(--text-muted); margin: 0 0 10px; display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.breadcrumb a { color: var(--text-muted); }
.post-body a, .author-desc a, .bp-page a, .series-box a { text-decoration: underline; text-underline-offset: 2px; }
.series-box { margin-top: 20px; padding: 16px 20px; background: #eef6fb; border: 1px solid #cfe2ef; border-radius: var(--radius); }
.series-box p { margin: 0; font-size: 15px; }
.series-box .series-title { margin: 0 0 6px; font-weight: 800; color: var(--navy); }
.related-posts { margin-top: 28px; }
.related-title { font-size: 18px; font-weight: 800; color: var(--navy); margin: 0 0 12px; }
.related-posts ul { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 10px; }
.related-posts li a { display: block; height: 100%; padding: 12px 14px; border: 1px solid var(--border); border-radius: 10px; background: var(--bg-elevated); color: var(--text); font-weight: 600; font-size: 15px; line-height: 1.5; }
.related-posts li a:hover { border-color: var(--blue-light); text-decoration: none; }
.comments-section .comments-title { font-size: 16px; font-weight: 800; color: var(--navy); margin: 0 0 8px; }

body.script:
//
  (function () {
    // Search toggle
    var searchToggle = document.getElementById('searchToggle');
    var searchBox = document.getElementById('searchBox');
    if (searchToggle && searchBox) {
      searchToggle.addEventListener('click', function () {
        searchBox.classList.toggle('open');
        var input = searchBox.querySelector('input');
        if (input && searchBox.classList.contains('open')) input.focus();
      });
    }

    // 카테고리 메뉴: 글이 아직 없는 카테고리는 숨김 (빈 카테고리 노출 방지)
    var catItems = document.querySelectorAll('.cat-nav li[data-label]');
    if (catItems.length && window.fetch) {
      fetch('/feeds/posts/summary?alt=json&max-results=0')
        .then(function (r) { return r.json(); })
        .then(function (d) {
          var used = {};
          var cats = (d.feed && d.feed.category) || [];
          for (var i = 0; i < cats.length; i++) used[cats[i].term] = true;
          for (var j = 0; j < catItems.length; j++) {
            if (!used[catItems[j].getAttribute('data-label')]) catItems[j].style.display = 'none';
          }
        })
        .catch(function () {});
    }

    // 같은 카테고리 글 (현재 글 제외 최신 4편)
    var rel = document.querySelector('.related-posts[data-label]');
    if (rel && window.fetch) {
      var cur = (rel.getAttribute('data-url') || '').split('?')[0];
      fetch('/feeds/posts/summary/-/' + encodeURIComponent(rel.getAttribute('data-label')) + '?alt=json&max-results=8')
        .then(function (r) { return r.json(); })
        .then(function (d) {
          var list = rel.querySelector('ul'), n = 0;
          (d.feed.entry || []).forEach(function (e) {
            if (n >= 4) return;
            var link = (e.link || []).filter(function (l) { return l.rel === 'alternate'; })[0];
            if (!link || link.href.split('?')[0] === cur) return;
            var li = document.createElement('li'), a = document.createElement('a');
            a.href = link.href; a.textContent = e.title.$t; li.appendChild(a); list.appendChild(li); n++;
          });
          if (n) rel.removeAttribute('hidden');
        })
        .catch(function () {});
    }

    // 자동 목차: 글(post)에서 h2가 3개 이상이면 첫 h2 앞에 목차 삽입
    var article = document.querySelector('.post-single[data-kind="post"]');
    if (article) {
      var body = article.querySelector('.post-body');
      var heads = body ? body.querySelectorAll('h2') : [];
      if (heads.length >= 3) {
        var box = document.createElement('nav');
        box.className = 'post-toc';
        box.setAttribute('aria-label', '목차');
        var title = document.createElement('p');
        title.textContent = '목차';
        var ol = document.createElement('ol');
        for (var i = 0; i < heads.length; i++) {
          var h = heads[i];
          if (!h.id) h.id = 'section-' + (i + 1);
          var li = document.createElement('li');
          var a = document.createElement('a');
          a.href = '#' + h.id;
          a.textContent = h.textContent;
          li.appendChild(a);
          ol.appendChild(li);
        }
        box.appendChild(title);
        box.appendChild(ol);
        heads[0].parentNode.insertBefore(box, heads[0]);
      }
    }

    // Reading progress bar
    var bar = document.getElementById('readingProgress');
    function updateProgress() {
      var h = document.documentElement;
      var scrollTop = h.scrollTop || document.body.scrollTop;
      var scrollHeight = (h.scrollHeight || document.body.scrollHeight) - h.clientHeight;
      var pct = scrollHeight > 0 ? (scrollTop / scrollHeight) * 100 : 0;
      if (bar) bar.style.width = pct + '%';
    }
    document.addEventListener('scroll', updateProgress, { passive: true });
    updateProgress();

    // Back to top
    var backBtn = document.getElementById('backToTop');
    function toggleBackBtn() {
      if (!backBtn) return;
      if (window.scrollY > 480) backBtn.classList.add('show'); else backBtn.classList.remove('show');
    }
    document.addEventListener('scroll', toggleBackBtn, { passive: true });
    if (backBtn) backBtn.addEventListener('click', function () { window.scrollTo({ top: 0, behavior: 'smooth' }); });
  })();
  //
